referenceSolutions.javascript:
export function solve(values, predicate) {
  return values.map(
    (x) => !(predicate === "positive" ? x > 0 : predicate === "even" ? x % 2 === 0 : x === 0),
  );
}

referenceSolutions.typescript:
type Value = any;
export function solve(values: Value, predicate: Value): Value {
  return values.map(
    (x: Value) =>
      !(predicate === "positive" ? x > 0 : predicate === "even" ? x % 2 === 0 : x === 0),
  );
}
